import { test, expect, Page } from '@playwright/test';

test.describe('User Authentication - Login with Valid Credentials', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000/login');
    await page.waitForLoadState('networkidle');
  });

  test('should successfully log in with valid email and password', async () => {
    // Fill in the email field
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');

    // Fill in the password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('ValidPassword123!');

    // Click the login button
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Wait for navigation to dashboard
    await page.waitForURL('**/dashboard');

    // Verify user is on dashboard
    const dashboardHeading = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardHeading).toBeVisible();

    // Verify user information is displayed
    const userGreeting = page.getByText(/welcome/i);
    await expect(userGreeting).toBeVisible();
  });

  test('should display user profile information after successful login', async () => {
    // Perform login
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('ValidPassword123!');
    await page.getByRole('button', { name: /log in/i }).click();

    // Wait for dashboard to load
    await page.waitForURL('**/dashboard');

    // Verify profile section is visible
    const profileSection = page.getByRole('region', { name: /profile/i });
    await expect(profileSection).toBeVisible();

    // Verify user name is displayed
    const userName = page.getByText('John Doe');
    await expect(userName).toBeVisible();

    // Verify user email is displayed
    const userEmail = page.getByText('user@example.com');
    await expect(userEmail).toBeVisible();
  });

  test('should maintain session after login and allow navigation', async () => {
    // Perform login
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('ValidPassword123!');
    await page.getByRole('button', { name: /log in/i }).click();

    // Wait for dashboard
    await page.waitForURL('**/dashboard');

    // Navigate to settings page
    const settingsLink = page.getByRole('link', { name: /settings/i });
    await settingsLink.click();

    // Verify settings page loads
    await page.waitForURL('**/settings');
    const settingsHeading = page.getByRole('heading', { name: /settings/i });
    await expect(settingsHeading).toBeVisible();

    // Navigate back to dashboard
    const dashboardLink = page.getByRole('link', { name: /dashboard/i });
    await dashboardLink.click();

    // Verify we're back on dashboard
    await page.waitForURL('**/dashboard');
    const dashboardHeading = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardHeading).toBeVisible();
  });

  test('should display logout option after successful login', async () => {
    // Perform login
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('ValidPassword123!');
    await page.getByRole('button', { name: /log in/i }).click();

    // Wait for dashboard
    await page.waitForURL('**/dashboard');

    // Verify logout button is visible
    const logoutButton = page.getByRole('button', { name: /log out/i });
    await expect(logoutButton).toBeVisible();

    // Click logout
    await logoutButton.click();

    // Verify redirected to login page
    await page.waitForURL('**/login');
    const loginHeading = page.getByRole('heading', { name: /log in/i });
    await expect(loginHeading).toBeVisible();
  });

  test('should persist authentication state across page reloads', async () => {
    // Perform login
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('ValidPassword123!');
    await page.getByRole('button', { name: /log in/i }).click();

    // Wait for dashboard
    await page.waitForURL('**/dashboard');

    // Verify dashboard is visible
    const dashboardHeading = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardHeading).toBeVisible();

    // Reload the page
    await page.reload();

    // Verify still on dashboard (session persisted)
    await expect(dashboardHeading).toBeVisible();

    // Verify user is still logged in
    const userGreeting = page.getByText(/welcome/i);
    await expect(userGreeting).toBeVisible();
  });
});
